import pandas as pd, numpy as np, os, json
from itertools import combinations

clean = pd.read_csv(os.path.join(output_dir, 'cleaned_data.csv'), dtype={'StockCode': str})
clean['StockCode'] = clean['StockCode'].astype(str)

# ---- Popular products analysis (ALL retained products) ----
prod = clean.groupby('StockCode').agg(
    quantity=('Quantity','sum'),
    revenue=('revenue','sum'),
    invoices=('basket_id','nunique')
).reset_index()
prod = prod.sort_values('revenue', ascending=False)
prod.to_csv(os.path.join(output_dir, 'popular_products_analysis.csv'), index=False)

# ---- Apriori ----
min_support = 0.03
max_len = 3
min_conf = 0.5

# basket -> set of products
baskets = clean.groupby('basket_id')['StockCode'].apply(lambda s: set(s))
all_basket_ids = baskets.index
n_baskets = len(all_basket_ids)

# prune infrequent singleton products
item_counts = {}
for s in baskets:
    for it in s:
        item_counts[it] = item_counts.get(it, 0) + 1
min_count = min_support * n_baskets
freq_items = {it for it, c in item_counts.items() if c >= min_count}

# build pruned baskets but keep ALL basket ids (empty allowed)
pruned = [ (s & freq_items) for s in baskets ]

# count itemsets level by level
from collections import defaultdict

def count_itemsets(candidates, baskets_list):
    counts = defaultdict(int)
    for s in baskets_list:
        for cand in candidates:
            if cand.issubset(s):
                counts[cand] += 1
    return counts

# level 1
level1 = {frozenset([it]) for it in freq_items}
counts1 = count_itemsets(level1, pruned)
frequent = {}
for k, v in counts1.items():
    if v >= min_count:
        frequent[k] = v

current = set(frequent.keys())
for length in range(2, max_len + 1):
    # generate candidates from previous frequent
    prev = [s for s in current if len(s) == length - 1]
    cand = set()
    for i in range(len(prev)):
        for j in range(i+1, len(prev)):
            u = prev[i] | prev[j]
            if len(u) == length:
                cand.add(u)
    if not cand:
        break
    counts = count_itemsets(cand, pruned)
    new_freq = {k: v for k, v in counts.items() if v >= min_count}
    frequent.update(new_freq)
    current = set(new_freq.keys())
    if not new_freq:
        break

# write frequent itemsets
rows = []
for itemset, cnt in frequent.items():
    rows.append({'itemsets': json.dumps(sorted(list(itemset))), 'support': cnt / n_baskets})
fi_df = pd.DataFrame(rows).sort_values('support', ascending=False)
fi_df.to_csv(os.path.join(output_dir, 'frequent_itemsets.csv'), index=False)

# association rules from frequent itemsets (len>=2)
rules = []
for itemset, cnt in frequent.items():
    if len(itemset) < 2:
        continue
    items = sorted(list(itemset))
    for r in range(1, len(items)):
        for ant in combinations(items, r):
            ant = frozenset(ant)
            cons = itemset - ant
            if not cons:
                continue
            ant_cnt = frequent.get(ant)
            if ant_cnt is None:
                continue
            conf = cnt / ant_cnt
            if conf >= min_conf:
                cons_cnt = frequent.get(cons)
                if cons_cnt is None:
                    continue
                lift = conf / (cons_cnt / n_baskets)
                rules.append({
                    'antecedents': json.dumps(sorted(list(ant))),
                    'consequents': json.dumps(sorted(list(cons))),
                    'support': cnt / n_baskets,
                    'confidence': conf,
                    'lift': lift,
                })
rules_df = pd.DataFrame(rules)
if len(rules_df):
    rules_df = rules_df.sort_values('lift', ascending=False)
rules_df.to_csv(os.path.join(output_dir, 'association_rules.csv'), index=False)

state_out = {
    'n_frequent_itemsets': int(len(fi_df)),
    'n_rules': int(len(rules_df)),
    'top_products': prod.head(10).to_dict('records'),
    'top_rules': rules_df.head(10).to_dict('records') if len(rules_df) else [],
    'top_itemsets': fi_df.head(10).to_dict('records'),
}
print('itemsets', len(fi_df), 'rules', len(rules_df))
